mapper.insert:
INSERT INTO PAYOUT_REQUEST (
    PAYOUT_REQUEST_ID, GROUP_ID, MEMBER_ID, ROUND_NO, REASON, AI_SUGGESTED_ROUND, STATUS, CREATED_AT
) VALUES (
             SEQ_PAYOUT_REQUEST.NEXTVAL, #{groupId}, #{memberId}, #{roundNo}, #{reason}, #{aiSuggestedRound}, 'REQUESTED', SYSDATE
         )

mapper.delete:
DELETE FROM CONSENT
WHERE CONSENT_TYPE = 'ORDER'
  AND TARGET_ID = #{payoutRequestId}

mapper.update:
UPDATE PAYOUT_REQUEST
SET STATUS = #{status},
    DECIDED_AT = CASE WHEN #{status} IN ('CONFIRMED', 'REJECTED') THEN SYSDATE ELSE DECIDED_AT END
WHERE GROUP_ID = #{groupId}
  AND PAYOUT_REQUEST_ID = #{payoutRequestId}
  AND STATUS = #{expectedStatus}

mapper.select:
SELECT MEMBER_ID
FROM GYE_MEMBER
WHERE GROUP_ID = #{groupId}
  AND STATUS = 'ACTIVE'
  AND MEMBER_ID != #{excludeMemberId}

mapper.insert:
INSERT INTO CONSENT (
    CONSENT_ID, CONSENT_TYPE, TARGET_ID, GROUP_ID, MEMBER_ID, AGREED_YN, AGREED_AT
) VALUES (
             SEQ_CONSENT.NEXTVAL, 'ORDER', #{targetId}, #{groupId}, #{memberId}, 'P', NULL
         )

mapper.select:
SELECT AGREED_YN
FROM CONSENT
WHERE CONSENT_TYPE = 'ORDER'
  AND GROUP_ID = #{groupId}
  AND TARGET_ID = #{targetId}
  AND MEMBER_ID = #{memberId}

mapper.update:
UPDATE CONSENT
SET AGREED_YN = #{agreedYn},
    AGREED_AT = SYSDATE
WHERE CONSENT_TYPE = 'ORDER'
  AND GROUP_ID = #{groupId}
  AND TARGET_ID = #{targetId}
  AND MEMBER_ID = #{memberId}
  AND AGREED_YN = 'P'
  AND EXISTS (
      SELECT 1
      FROM PAYOUT_REQUEST pr
      WHERE pr.GROUP_ID = #{groupId}
        AND pr.PAYOUT_REQUEST_ID = #{targetId}
        AND pr.STATUS = 'CONSENT_PENDING'
  )

mapper.select:
SELECT COUNT(*)
FROM PAYOUT_REQUEST
WHERE GROUP_ID = #{groupId}
  AND ROUND_NO = #{roundNo}
  AND STATUS = 'CONFIRMED'
  AND PAYOUT_REQUEST_ID != #{excludeRequestId}

SELECT PAYOUT_REQUEST_ID, MEMBER_ID
FROM PAYOUT_REQUEST
WHERE GROUP_ID = #{groupId}
  AND ROUND_NO = #{roundNo}
  AND STATUS IN ('REQUESTED', 'CONSENT_PENDING')
  AND PAYOUT_REQUEST_ID != #{excludeRequestId}
FOR UPDATE

mapper.update:
UPDATE PAYOUT_REQUEST
SET STATUS = 'REJECTED',
    DECIDED_AT = SYSDATE
WHERE GROUP_ID = #{groupId}
  AND ROUND_NO = #{roundNo}
  AND STATUS IN ('REQUESTED', 'CONSENT_PENDING')
  AND PAYOUT_REQUEST_ID != #{excludeRequestId}

UPDATE GYE_GROUP
SET ORDER_CONFIRMED_YN = #{yn}
WHERE GROUP_ID = #{groupId}

mapper.select:
